(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,649046,e=>{"use strict";var i=e.i(843476),l=e.i(811337);function n(e){let n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=n;return r||s("AnketaCollapse",!0),c||s("AnketaGroup",!0),d||s("AnketaList",!0),h||s("AnketaPoint",!0),j||s("AnketaProse",!0),x||s("Whisper",!0),(0,i.jsxs)(c,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(d,{children:[(0,i.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Августин Линдберг | Augustine Lindberg"})}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"«Август» — часто употребляемое сокращение имени;"}),"\n",(0,i.jsx)(n.li,{children:"«Стейн» — для близких людей, прозвище, данное Эридой в детстве;"}),"\n",(0,i.jsx)(n.li,{children:"«Аид» — прозвище, используемое на чёрном рынке. Многие заказчики узнают Августа именно по этому прозвищу, когда он находится под маской. Значение корректнее всего трактовать именно как «символ прошлого», ведь, обладая возможностью практически без преград проникать в голову и получать нужную информацию о том или ином грешнике, он смог стать очень неприятным врагом для многих, кто попадался ему на пути. Говорят, что при первом же знакомстве он обязательно использует на других свои способности, точно впиваясь в душу."}),"\n"]})]}),(0,i.jsx)(h,{title:"Возраст",children:(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"прожитый на земле: 50 лет."}),"\n",(0,i.jsx)(n.li,{children:"дата рождения — 07.01.1550г. | смерти — 09.03.1600г."}),"\n",(0,i.jsx)(n.li,{children:"прожитый в Загробном мире как грешная душа: 418 лет"}),"\n"]})}),(0,i.jsx)(h,{title:"Пол",children:(0,i.jsx)(n.p,{children:"Мужской"})}),(0,i.jsxs)(h,{title:"Раса",children:[(0,i.jsx)(n.p,{children:"Ногицунэ."}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Аристократ, полный решимости, жестокости и гордыни в своих действиях. При жизни Август был одним из тех, кто наслаждался чужими мучениями в любой из возможных форм, в приоритете одна из которых отображается в изнасиловании и пытках. Иногда убийствах;"}),"\n",(0,i.jsx)(n.li,{children:"Добившись законного наследства и не бедного, хоть и не богатого вдоволь положения, мужчина посмел отдать себя на попечение плотской жизни и довольствовался светской общиной. И хотя во многом он был наполнен неистовостью и даже ненависть к устрою, которому жил, Август стремился найти себя в этом мире и поймать волну отдушины, которой и стала мирская мечта с кузиной. Сложно сказать, сколько невинных жизней загубил своими играми Август до момента цели, развлекаясь с различными девушками, то ли сами решавшиеся по воле поддаться во грех, то ли это были более бедные, но не менее любопытные служанки;"}),"\n",(0,i.jsx)(n.li,{children:"В каком-то смысле его можно было назвать и маньяком без капли морали, что стремился победить своих врагов сначала довольно мягким способом, но если не выходило, то в ход пускались различные ресурсы, которые не особо выставляли его в хорошем свете. Причиной подобных безрассудств, в том числе убийства кузена и желание заполучить всё то, что принадлежало ему, стала остервеневшая зависть и желание завладеть той, кого он любит всю жизнь."}),"\n"]})]})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"«Человек, теряющий рассудок, утрачивает и собственную волю» — эта мысль всё чаще возвращалась к Августу в моменты внутреннего напряжения. Со временем она перестала быть отвлечённым наблюдением и стала ассоциироваться с одной-единственной слабостью, которую он долго предпочитал не называть... Его болезненная привязанность к кузине постепенно начала восприниматься как нечто чужеродное: неотделимое от него самого, но в то же время подтачивающее личность изнутри, словно паразита, питающегося жаждой обладания – и оттого раздражающего, но которому невозможно в полной мере отказать. Именно рядом с ней Август впервые замечал за собой утрату привычной сдержанности — ту редкую, но опасную потерю дистанции и холодности, которая шла вразрез с образом, отточенным годами, обращаясь в горячую жажду и страстность."}),(0,i.jsx)(n.p,{children:"Обращаясь к ретроспективному осмыслению, он всё чаще приходил к выводу, что подобные сбои недопустимы. Любая утрата самообладания грозила нарушить выверенный порядок, а вместе с ним — лишить его тех преимуществ, на которых держалось всё существование. Это понимание, конечно же, не привело к раскаянию, но усилило внутреннее напряжение: он стал заметно мрачнее, злее и куда менее доверчивым, постепенно превращая настороженность в привычное состояние, выраженное на сегодняшний день. Подозрительность и склонность к избыточному контролю укоренились в нём ещё сильнее, а сама мысль о повторении подобной уязвимости начала вызывать раздражение и скрытую тревогу, но одновременно и вопиющую ломку."}),(0,i.jsx)(n.p,{children:"Август Линдберг в светском обществе всегда являлся эталоном безупречного: на пёстрых балах он устраивает пиршества, достойные аристократов, легко поддерживает идеальность и редко позволяет усомниться в корректности. В то же время, он воспринимает людей скорее как элементы сцены, нежели как самостоятельные личности – чужие судьбы для него не представляют ценности сами по себе; куда больший интерес вызывает возможность вмешаться в них, изменить направление и наблюдать последствия. Ему не свойственно испытывать сочувствие или сопереживание, и потому чужая боль не отталкивает его — напротив, она вызывает бессовестный экстаз. В нём есть в том числе нехитрое стремление контролировать каждый шаг тех, кто мимолетно попадает в сферу его интересов, внимательно отслеживая слабости, страхи и привязанности – в данном случае контроль для него выступает одновременно чувством свободы и всевластия (господин положения), и одновременно формой подтверждения собственной значимости."}),(0,i.jsx)(n.p,{children:"Со временем фокус Августа сместился, и вылился из телесного удовольствия в более сложную и извращённую форму. Натура ногицунэ крайне любопытна: в нём живет экспериментатор, склонный проверять границы допустимого, как в физическом, так и в психологическом плане. Однако простого обладания ему стало недостаточно: истинное удовлетворение он находит в процессе разложения жертвы; его стала привлекать возможность подчинить не только тело, но и волю, лишить человека опоры, разрушить его социальные связи и чувство собственной ценности."}),(0,i.jsx)(n.p,{children:"Естественно, не просто так Августу могут довериться некоторые наивные души – он наблюдателен, внимателен, хорошо считывает людей и подстраивается под их ожидания. Он редко говорит лишнее, тщательно контролирует речь и поведение, что делает его крайне сложным объектом для прямых обвинений. А если и вовсе возникает угроза разоблачения, он либо заранее подготавливает себе алиби, либо перекладывает ответственность на других."}),(0,i.jsx)(n.p,{children:"Лояльность для такого человека, как Август, возможна, но исключительно в иерархичном порядке, где он занимает доминирующее положение. Любые обещания и клятвы для него не имеют морального веса и легко нарушаются, если это становится выгодным. В нём присутствует склонность к долгосрочному планированию, хотя мужчина и не лишён импульсивных срывов (сейчас – уже реже, вглядываясь в прошлое), когда дело касалось его помешанности на любви детства. Чувство привязанности, застыв в искажённой форме, стало апофеозом безумия и преследования образа утраченного, недоступного идеала, которое он пытается в том числе найти в своих новых жертвах, но неминуемо оказывается разочарован. Невозможность реализовать такую привязанность усилила его фрустрацию, зависть к другим и стремление к контролю, что во многом стало катализатором его желания подчинять и ломать других, компенсируя собственную неудовлетворённость."}),(0,i.jsx)(n.p,{children:"Говоря об этом более открыто, стоит уточнить, что Август никогда не проявлял зависть открыто и примитивно, ведь в его жизни было достаточно богатств, достойное положение графа, и он обрёл признание. Вместо этого зависть обрела иную форму – едкую, мерзкую, рождённую из желания невозможности позволить другим сохранить то, что ускользало от него самого. Наиболее остро это чувство проявлялось в присутствии тех, чья жизнь сохраняла целостность без усилия, — людей, способных испытывать привязанность, не превращая её в слабость, и быть рядом с кем-то. В них Август видел то, что не мог удержать в себе: естественность, внутреннее равновесие, право на чувство без унижения. Всё это вызывает в нём не только жгучий грех, но и неприязнь, поскольку напоминало о той, с кем он не мог быть вместе долгое время, и которую, даже обретя, всё равно потерял. Возможно даже навсегда, раз она не может вспомнить о нём… Его привязанность к кузине стала первым и самым наглядным источником зависти по молодости – недоступность образа, невозможность подчинить, а главное — существование других, способных находиться рядом с ней без утраты самообладания, вызывали в нём гнетущее чувство, которое он до конца не мог понять и сам. Зависть со временем утратила всякую романтическую окраску, превратившись в навязчивую потребность лишить объект той свободы, которая оставалась для него недостижимой."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Страх потери нажитого",children:(0,i.jsx)(n.p,{children:"Страх потерять материально нажитое. В ходе всей своей жизни всего того, что добился Август, он искренне боялся потерять, что подтверждается его крайне жестоким отношением к вопросам о поиске жены и заведении наследников для передачи всего нажитого. Ныне данный страх перевоплотился в нежелание терять те личные вещи, что стали составлять его редкое сокровище в связи со скрытным образом жизни."})}),(0,i.jsx)(h,{title:"Страх не найти вдохновение",children:(0,i.jsx)(n.p,{children:"Не найти то, что вернёт ему вдохновение. В последнее время Август чертовски раздражён и злобен, как бы не пытался это скрывать, из-за того, что не может найти себе ту душу, на которую смог бы выместить всё, что накопилось у него за весь период жизни. Перед своей гибелью Август решил, что хочет за год или даже два, но оторваться так, чтоб и умирать жалко не было. К этому страху можно в принципе отнести и страх смерти в форме преждевременной: пока Август не добьётся своей цели, внутри он будет противостоять смерти всегда."})}),(0,i.jsx)(h,{title:"Страх отсутствия сопротивления",children:(0,i.jsx)(n.p,{children:"Страх отсутствия сопротивления. Удовольствие Август получает преимущественно от развращения плоти и души, что проявляет сопротивление, которую можно сломать и покорить. Если жертва не хочет вырваться на волю, к ней быстро теряется интерес, а Август живёт целью найти ту, что никогда его не разочарует."})}),(0,i.jsx)(h,{title:"Страх потери близких",children:(0,i.jsx)(n.p,{children:"Невзирая на собственную жестокость и отношение к жертвам, своих близких родных в любом случае ценит. По этой причине крайне боится их потерять. Из-за довольно трагичной смерти большинства его близких (особенно кузины), даже если кажется безразличным, никогда бы не хотел повторить ту историю, с которой столкнулся в жизни. Хочет счастливого будущего для неё, и беспокоится, что может сломать это."})})]})}),(0,i.jsx)(r,{title:"Мечты, цели",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Бывшая цель и ныне насущная мечта, которая, как ему кажется, никогда уже не исполнится — помочь своей кузине вспомнить о том, какие между ними были отношения последнее время, их брак. Ещё к одной из возможных мечт можно отнести желание позабыть всё: скучающий и практически не видящий в смысле жизни, неудовлетворённый Август на свои 418 лет, невзирая на вежливость и обаятельность, уже просто существует, но ему хотелось бы вновь ощутить вкус той остроты и страсти — и если ничего из этого не воплотится, он пожелал бы тоже отдаться забвению. Но пока что его на плаву держит охота."}),(0,i.jsx)(n.p,{children:"Из действующих целей можно отметить поиск жертвы через свои источники и длительные наблюдения. Помимо этого, он хочет стать коллекционером, т.е. тем, кто охотится за крайне редкими существами. Его целью является становление профессиональным охотником, хотя, откровенно говоря, Август не приветствует работу в команде, что задерживает его поднятие в карьерной лестнице внутри Карнавала."})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Свою историю он начинает в зачатках и просторах Датско-норвежского королевства к 1550 году, государём которого является человек из рода Ольденбургов — Кристиан III, пришедший ко власти через Графскую распрю. После того как был осуществлен переворот с помощью наемных немецких воинов, католицизм потерпел поражение. В 1547 году в Дании состоялось событие, имеющее важное значение в истории страны. Король созвал собрание профессоров и пасторов из королевства и двух герцогств с целью разработки структуры протестантской церкви. В сотрудничестве с богословами был разработан документ, придерживающийся духа религиозных наставлений. Этот проект был послан Лютеру на немецком языке для корректировок. Лютер и другие богословы из Виттенберга одобрили документ. После внесения незначительных поправок Виттенберга, король просил Бугенхагена завершить работу, опираясь на свой опыт и мудрость. Учение, структура и богослужение датской протестантской церкви в основном основывались на проекте короля и богословов. Устав был подписан не только королем, но и двумя профессорами из каждого колледжа, а также ведущими пасторами. Все эти события способствовали расцвету протестантизма, который впоследствии стал ключевым элементом в усилиях Августа. Это открыло путь к обогащению наследия и перерождению ради одной цели."}),(0,i.jsx)(n.p,{children:'На свет мальчик появляется глубокой ночью, был назван как "Августин", где смысл с латинского весьма подходил — "великий, величественный, священный".'}),(0,i.jsx)(n.p,{children:"Отец и мать у Августа были католиками, и несмотря на то, что Норвегия вынуждена была подчиниться протестантизму, некоторых вещей, которые они передали со знаниями ребёнку, это не касалось: католических ритуалов и обрядов, символики и икон, представлений о католической литературе. Конечно, о них запрещено было разглашать, однако сохранение католической идентичности было одной из важнейших частей, сыгравшей в истории Августа."}),(0,i.jsx)(n.p,{children:"Был единственным сыном, однако не единственным ребёнком, так как у него была старшая на 16 лет сестра. В то же время, мальчишку это не сильно обижало, ведь он был любимцем семьи — избалованный наследник, любимый и долгожданный, вокруг которого всем приходилось ходить на цыпочках, как с принцем. Казалось бы, и не предвещало ничего беды, ведь у Августа всегда было всё и смысла завидовать никогда не было. С сестрой он виделся не слишком часто."}),(0,i.jsx)(n.p,{children:"С возрастом Август, помимо получения подготовительного образования, бывало, разъезжал в путешествия с семьёй: на те времена у них были крайне близкие по линии деда отношения с семьёй испанских маркизов Диасов. С ужесточением законов, конечно, именно Линдбергам приходилось ездить из Германии (к старшей сестре в гости) в Испанию, в то же время, Август проводил время со своим старшим кузеном в детстве, оставаясь то на летнее время, то на зимнее по возможности. Отношения Раймона и Августа изначально строились в положительном ручье, у них было много общих увлечений, насколько позволял возраст: никогда не дрались, были почти что братьями, не-разлей вода. В то же время, их пути расходятся, когда Раймон начинает серьёзно увлекаться морскими путешествиями и кораблями, в то время как Августа привлекала суета светского общества."}),(0,i.jsx)(n.p,{children:"Кроме того, многое поменялось с тех пор, когда Август стал смотреть на свою младшую кузину — Эриду — особенным образом: сначала маленькая девочка-забияка, почти что вредительница, ходящая за Раймоном и Августом хвостиком, выросла в прелестную молодую красавицу."}),(0,i.jsx)(n.p,{children:'Свои первые воспоминания о них Август не забудет даже сквозь жесточайшие кошмары и потери, как он увидел её: волосы, густые и глубокого чёрного цвета, обрамляли ее лицо, придавая ему загадочность и нежность. Она носила свои волосы убрано в аккуратную прическу, где пряди были нежно завиты и прикрашены тонкими лентами, добавляя ей женственности; ее кожа, мягкая и светлая, была ухоженной и никем не тронутой, а нежные румяна на щеках добавляли ей свежести и живости. Для тогдашних лет, 16-летний Август, находящийся в самом рассвете пубертатных позывов, понял, что заглядывает он на кузину не так, как свойственно порядочному родственнику: он нервно сглатывал в страстных желаниях и отвратительных мыслях, да помышлял о том, как было бы чудесно забрать её к себе, с собой. Август ещё не знал, что его желания обратятся в фанатичные "она станет моей", "я буду обладать ей", однако был затемнён ими, будто пеленой.'}),(0,i.jsx)(n.p,{children:"К этому моменту взрослые семейства Диасов начинают серьёзно подготавливать Эриду к первому дебюту, за которым Август следил (конечно, насколько ему было позволено) с придыханием, ведая о том, как гадкий утёнок превращается в прекраснейшего лебедя. В те периоды Раймон уже поступил на службу и активно плавал вместе с маркизом, хотя заслуженный отдых Раймона в промежуток между 20-22 годами позволяет Августу узнать старшего кузена с новой стороны: свободолюбивый, помешанный и не ценящий того, что у него есть. Особенно это мнение закрепится за Августом, когда он узнает о неудачном романе Раймона в будущем. Однако куда большую боль принесло Августу совсем иное событие."}),(0,i.jsx)(n.p,{children:'За теми редкими, но сладкими исключениями, когда Август мог быть приглашён на грандиозные праздники, Линдберг жадно грезил встретиться с Эридой, пожирая бездной, разрывающей изнутри осознанием — он мечтает о кузине. В похотливом, развращённом образе, приправленным крупицами нежности и заботы, которой он готов был её одарить. Как же ему хотелось жениться на ней! Август с ненавистью скалился на маркизу Диас за то, как она порхала вокруг аристократов с понятной для всех целью — найти для дочери достойную партию. "А чем недостоин внимания и я, маркиза Диас?" Однако сделать ничего он не мог, ведь и Августа никто бы не понял: ни старший кузен, ни дорогие родители, придерживающихся строгих и глубинных католических убеждений (естественно, скрытых за спинами от протестантизма). Можно было сказать, что и Диасы, и Линдберги, из-за общих семейных ценностей, не приветствовали кровосмешений. Понимая, что у Августа мало шансов, — что чертовски его раздражало до сильнейших нервных срывов — он решил, что обязан стать лучшим. Достойным. И, конечно же, он подарил Эриде всю свою искреннюю первую любовь, оставшуюся с ним на всю далёкую жизнь. Их отношения в подобном ключе начинались с первых непроизвольных, затягивающихся взглядов и улыбок, некоторые разговоры становились стеснительными и даже неловкими.'}),(0,i.jsx)(n.p,{children:"Буря эмоций переполняла Августа: радость от встреч и общения, волнением перед каждой редкостной встречей, невероятным счастьем при виде улыбки или слышимом голосе возлюбленной, словно он слышал пение ангела, встречающим его перед вратами в рай."}),(0,i.jsx)(n.p,{children:"Когда Эриде исполнится 15 лет, между ними завяжется алая нить уз, когда Август впервые решился прикоснуться к Эриде, впервые поцеловать её, поделиться чувствами и намерениями. Тогда Август ещё не знал, какую ошибку совершил, заставив обратить в пепел всё уважение к Раймону и к себе. Между братьями состоялся крайне тяжёлый, горячо нравоучительный и пояснительный диалог о том, что Августа он не желает больше видеть в доме. Это крайне сильно ударило по гордости Линдберга, ведь Раймон воровал у него годы, месяцы, а может даже минуты последнего бытия с Эридой."}),(0,i.jsx)(n.p,{children:"К счастью, Раймон не доложил маркизу и графу об этом, в то же время, Августу правда пришлось уехать. С глубочайшей раной на сердце, жёстко треснувшей в момент, когда он узнаёт, что кузину отдали замуж — и никто не осмелился предотвратить подобного. Так отношения между братьями возросли в бесконечную пропасть. Август копал под эту слащавую мразь Ледесма и ненавидел всем сердцем. Однако оставаться рядом или встречаться не мог, так как отец определил его будущее быстрее."}),(0,i.jsx)(n.p,{children:"В 18 лет Август поступает в Гейдельбергский университет на теологический факультет, и ему приходится забывать о возможности путешествовать в Испанию. С удушающей болью в груди он не простил себе, что не посетил свадьбы Эриды, однако осознавал, что не удержался бы от убийства. Чтобы справиться с болью и осознанием, не готовый смириться, он решил, что добьётся Эриды всеми способами. Даже если ему придётся совершить невозможное. Возможно, именно поэтому Август, как норвежский католик, не переносящий узурпации датской короны, пересилил себя и решил углубиться в кальвинизм, подносимый университетом. Это был не выбор будущего от лица Августа, однако будущее, дарованное отцом для того, чтобы он добился власти и богатства в текущих реалиях. Стал признанным норвежским графом в Дании. Август принял эту цель."}),(0,i.jsx)(n.p,{children:"За годы учёбы Август сосредоточился и посвятил себя полностью достижению первых, насколько мог себе позволить, мест. Характер его ужесточился, сам он стал чёрствым, проснулись ноты нордичности, что позволяет ему заводить связи, однако не сближаться с другими людьми и держаться строго. Они были ему не нужнее, чем вилка да ложка — лишь инструменты. Воспринимая их таким образом, да почивая в достижениях, Август забирает ту простынь гордыни. И не безосновательно: ему симпатизировал рациональный подход с недоверием к мистике. Не поленившись, он пропустил через себя немало исповеданий с изложениями о Боге, один из которых был и Гейдельбергский катехизис, выпущенный годами раннее. И хотя Август не забывал о мотивации, заложенную в подкорку мозга, казалось, Август был похож на камень. Стейн, как его называла Эрида в детстве."}),(0,i.jsx)(n.p,{children:"В 20 лет Август не без труда узнал о том, что произошло в семье Диасов — несколько дуэлей, в ходе которой Раймону приходится стать привязанным к дому и принять почести. На это Август не мог не реагировать злорадно, хотя в том же году в его голове зародился план о том, как можно было бы заполучить себе испанские земли. Весьма долгое время ему приходится собирать для осуществления плана информацию. В 22 года Август не поленится изучить геологическое древо семьи для того, чтобы в целом понять, какие у него были шансы и возможные связи для будущего. Здесь его привлекла германская семья О'Каннингем, к которой он в эти же года и поедет, основательно подготовившись. Несколько часов езды не разочаровали — он столкнулся с более-менее состоятельным наследником семьи, что числился ему дядей. Младшие из дядей разбрелись по свету кто куда — погибли, отправились в церковные места, стали наёмниками."}),(0,i.jsx)(n.p,{children:'Дядя оказывается зависимым, а вот младшая тётушка — весьма миловидной девочкой лет 14. Августу приходится втираться в доверие, однако он не постеснялся воспользоваться азартностью и пьянством родственника. Организовав небольшой закрытый и подпольный игровой клуб, ему приходится уговорить друзей и взять их в долю для того, чтобы удачно надурить несчастного на сумму. Благодаря обману Август умудряется разыграть спектакль, проиграв своим друзьям немалую сумму. Воспользовавшись пьянством и любовью к играм у дяди, он вопрошает о неплохом займе, так как остался в дураках у друзей. То ли по доброте душевной, то ли из-за общей харизмы, а может симпатичности Августа, мужчина одобряет ему займ за услугу. Которая, конечно, не состоялась. Август нанял немецких наёмников, как любили практиковать датчане, для того, чтобы прирезать несчастного, а сам, до начала мероприятия, выкрал младшую "тетушку".'}),(0,i.jsx)(n.p,{children:"Милосердие?"}),(0,i.jsx)(n.p,{children:'Совсем нет. Она была похожа на Эриду. Как щелчок затвора в его голове всплыли со дна воспоминания, заставивших надругаться над малолетней девочкой. Всё начиналось нежно и медленно, Август не планировал поначалу вредить ей, убеждая в том, что если она будет с ним вежливой и хорошей, то получит шанс на будущее. В конце концов, семья Каннингемов не отличалась хорошей кровью, а вот Линдберг был уже практически графом в силу старости отца — через год он вернётся и переймёт титул. Девочка продолжала сопротивляться и не хотеть, однако Август не обращал внимания на просьбы, прикасаясь к миловидной коже, поглаживая волосы и стягивая потихоньку ткани с полузрелого тела. До его ушей не доносились крики, а если быть точнее, он заставлял её молчать. Несколько дней в отдалённом доме, которые сняли друзья ему для охоты, пока сами развлекались в городе на деньги, Август изнасилует несчастную весьма жестоко. "В конце концов, ты похожа на неё, но ты — не она. Ты не заслуживаешь этой нежности". Придя к осознанию, что разум его был затуманен влюблённым образом к другой персоне, Августу стало от себя в одной степени мерзко, но с другой — понравилась власть и безнаказанность. Не такова была его любовь к Эриде, зато с ней он может сделать что захочет. Он изуродовал девочку после насмехательства, оставляя на несчастной тяжёлые шрамы, заставляя кровоточить и промерзать. В конце концов, он отводит её в лес и умертвляет. Так началось его пристрастие к охоте — не только на животных, но и на миловидных особ, откликающихся в душе воспоминаниями об Эриде.'}),(0,i.jsx)(n.p,{children:"В 22 года Август, колыхнувшийся грёзами об Эриде, наконец пишет ей письмо. Их общение возобновляется."}),(0,i.jsx)(n.p,{children:"В 23 года Август с отличием заканчивает университет, не привлекаемый к ответственности. Он благополучно вернётся с деньгами, которые разделил между друзьями, в Норвегию, для того, чтобы стать графом Линдберг. Отец уже был болен и скончался, а вот матушка покинула мир заметно раньше. К сожалению, из-за психических сдвигов молодого человека, в нём не откликнулось сожаление или грусть, ведь он знал, что их души обретут покой. Да и, мягко говоря, фокус внимания был смещён в иную сторону."}),(0,i.jsx)(n.p,{children:"В этом же году Август узнаёт о том, что многие вещи, касающиеся её жизни, оказались отвратительными. Во многом из-за поведения мужа. И хотя девушка не писала об этом напрямую, едкое предчувствие заставляет Августа проститься со своей гордыней и возобновить отношения с Раймоном, вернувшись в Испанию. Он делится переживаниями с кузеном, наследство пока не волновало графа. Точнее говоря, братья, можно сказать, помирились на некоторое время, объединённые одной целью, а именно — освободить Эриду. Так они начали наблюдать за жизнью семьи Ледесма, докапываясь до истины. Конечно, Август подолгу задерживаться никак не мог, ему приходилось в силу личных целей отлучаться, однако он поддерживал активное общение с кузеном."}),(0,i.jsx)(n.p,{children:'В 25 лет Август наконец-то начинает видеться с Эридой, между ними вновь загораются те хрупкие и потерянные чувства, несмотря на расстояние и время. Конечно, встречи организованы были со стороны Раймона и проводились в тайне от мужа. Линдберг так и не понял, был ли согласен Раймон с их отношениями или же выбирал "наименьшее зло", однако дареному коню в зубы не смотрят. Эрида была уже зрелой женщиной, у неё был ребёнок, однако это не отвратило Августа, несмотря на то, как тошно было представлять, как к этому телу и душе прикасался другой мужчина. В эти годы граф начинает жёстко курить и недосыпать из-за кошмаров, однако в голове созревал план, шестерёнки вертелись.'}),(0,i.jsx)(n.p,{children:"До 29 лет жизнь Августа была праздной и торжественной, он был страстным организатором костюмированных балов для своих аристократических друзей и знакомых. Он уделял особое внимание каждой детали и создавал тематические вечеринки, воссоздавая атмосферу разных эпох и культурных периодов. В течение данного периода все, хоть на каплю кто напоминал ему Эриду, встречал неприятный конец для себя — надругательство и смерть. Он похолодел, был красивой, однако ужасающей смертью для всех влюбляющихся молодых девушек. Август настолько желал Эриду, что окончательно слетел с катушек, срывая все грязные мысли и очищая их телами других девушек для того, чтобы Эриде досталась лишь ангельская колыбель. И с каждым разом деятельность его была куда более омерзительной. Впрочем, Август старался быть аккуратным и не вызывать событий, что опорочат его имя."}),(0,i.jsx)(n.p,{children:"В каком-то смысле его невозможно было оторвать от праздных и шумных мероприятий, однако Август был не согласен действовать в ущерб себе — он не забывал о целях и старательно хотел выслужиться перед датской короной. Высокое и достойное образование вместе со связями дали эту возможность — ему открылись двери датского светского общества. Конечно, из-за бытия норвежским графом ему приходилось мириться с королевскими указами и инструкциями, однако корона позволила Августу пользоваться расширенными полномочиями, проводя административные и церемониальные функции на своих землях без проблем. На суды, конечно, приходилось регулярно ездить в Копенгаген, однако Линдберг не был против подобных инициатив. Напротив, это позволяет ему обзавестись знакомствами и напоминать о себе. В то же время, Август неплохо держался наплаву: он умело выдерживал баланс между приказами и желаниями жителей. Августу, на деле, никогда не было любопытно удовлетворение обеих сторон, он старался работать на репутацию и сглаживать острые углы."}),(0,i.jsx)(n.p,{children:"Дела идут вполне себе хорошо, несмотря на то, что Норвегия застыла в стагнации, так как экономически Ганза отняла все шансы. Это не сильно мешает Августу, так как в датском дворянстве он себя зарекомендовал и закрепился на удачной позиции по старой дружбе. Этим другом был его университетский товарищ, датчанин, с которым они заключили сделку и обещание, данное на золотых часах. Так они помогали друг другу и прикрывали спины во всех начинаниях. Наконец, когда мужчина набирается власти, а Раймон сумел надурить Амадо Ледесме, Август возвращается в Испанию. Кузену уже был известен план Линдберга — и они приступили к его осуществлению."}),(0,i.jsx)(n.p,{children:'Тяжелую ношу планов братья разделили предусмотрительно точно между собой: Раймон играл на доверие Ледесме и пользовался возможностями уловок на обогащение, в то время как Август совершил всю грязную работу и заготавливал почву. Когда дело было решено, Ледесме был обанкрочен со стороны Раймона, а Линдберг сжёг его поместье. Сами же братья закрыли мужчину и мучительно пытали. "На сим святейшим теле ты оставлял шрамы и раны. Интересно, долго твоя свинья морда будет жить со вспоротыми потрохами? Вот и проверим. Постарайся прожить, дабы я насладился твоими муками. Кстати, я чудесный собаковод. Знал бы ты, сколько они сожрали кровящих девиц."'}),(0,i.jsx)(n.p,{children:"Несмотря на то, что каждый, даже Эрида, умудрилась поиздеваться над мужем, самым жестоким среди них был Август: он предпочитал устраивать поножовщину, стрелял и скалился, а затем спускал любимых охотничьих собак — и те с удовольствием обгладывали полуживого Ледесме."}),(0,i.jsx)(n.p,{children:"Финальным штрихом они сожгли мученика."}),(0,i.jsx)(n.p,{children:"Убедившись в безопасности жизни Эриды, братья решили слаженно отработать на авторитет, дабы выйти в произошедшем сухими из воды и без единых подозрений. Августу тяжело терпеть в этот период, зная, что до Эриды можно было дотянуться ладонями и чувственно обнять, прильнуть к ней и зарыться в тёмные волосы. Лишь в возрасте 31 года Август дождётся, когда женщина окажется в его руках под венцом. Он забирает её в Норвегию, конечно, не без церемоний и сложностей. До 38 лет они живут счастливо, указанные семь лет становятся долгожданной и упоительной наградой в моменте, ведь Линдберг наконец-то смог добиться всего. Единственное, что рушило идиллию их семейной жизни, это сын от первого брака, которого Август откровенно терпел и не желал видеть. Однако видя, какие чувства испытывала к чаду жена, не решался пойти на жестокий поступок. И, к счастью, она не видела за влюблёнными глазами и мягкой улыбкой леденящего взгляда, который вытягивал из Иаго душу. Едва ли Август сдерживался от того, чтобы не спустить поводки собак, крутя их меж пальцами, а животных удерживая у ноги. Слюни их безумно истекали, глаза были бешеными, а Август мрачно усмехался. Психопат."}),(0,i.jsx)(n.p,{children:'Да, Иаго здесь были не рады. Особенно, когда Эрида дарит ему благословение — рожает близнецов, мальчика и девочку, которых Август будет любить ценнее себя и жизни, вместе с Эридой. Возможно, будь Линдберг нормальным человеком, а не больным, он бы остановился на имеющемся и наслаждался шансом. Однако же, он был злопамятным человеком, и все, на кого Август положил глаз, получат отмщение. В моменты Непобедимой армады, когда Раймон отправился на корсарскую службу, Август специально нашёл наёмника для того, чтобы отправить в путешествие и убить кузена: он не мог простить, не удалось, те чувства, которые волнительно скапливались в нём, несмотря на то, что Раймон одобрил в конце концов брак. "Если бы ты сразу открыл рот, всё бы было иначе. Прости, брат, мою ненависть. Но всему воздаётся".'}),(0,i.jsx)(n.p,{children:"Маркизат, оставшись без мужского наследника, естественным образом требует немедленного вмешательства. Август, предусмотревший все ходы наперёд, пишет Филиппу II во прошение о том, чтобы, как единственному наследнику (ближайшему) по мужской линии, вручили подданство и титул. Он же, со своей стороны, примет католичество и все накопленные средства вывезет в Испанию. Получив одобрение, Август без промедления организовал переезд, самой же Эриде сказав о том, что это для того, чтобы почтить память о брате, видя, как она была разбита."}),(0,i.jsx)(n.p,{children:"Так Август стал испанским маркизом, отрекаясь от жизни в датско-норвежском королевстве. Очень многие друзья были недовольны его выбором, впрочем, никто из них не попрекал, если говорить о близких. Удобно же иметь католика со связями, аристократа? Вдруг понадобится. В это же мгновение Иаго покидает отчий дом, что позволяет Августу окончательно выдохнуть и жить той жизнью, которая достойна его. Два года они жили счастливо и без происшествий, пока Эрида не покидает мир по непонятной причине. Жизнь Августа словно разбивается надвое, как хрустальная ваза, падая с церковных куполов — вдребезги. Это за смерть кузена?..."}),(0,i.jsx)(n.p,{children:"Любовь всей его жизни покидает Августа, когда ему исполняется 41. Мужчина остаётся один с детьми на руках, близнецами, которым по шесть лет. В его глазах отражается утрата, столь тяжелая, что словами едва ли можно выразить всю глубину его больших чувств. Тени невыразимого отчаяния исказили его душу, смешав сознание и бессознательное в одну сложную картину страдания. Его шаги стали медленными, будто он плывет в океане печали. Пустота в его груди, как черная дыра, затягивает в себя каждую попытку найти хоть какой-то смысл. Он воспоминает каждый момент, проведенный рядом с Эридой, словно перелистывая страницы книги, где каждая строка написана с любовью и теплом. Он мучается воспоминаниями о смехе, ободряющих словах и нежных касаниях, вырывая с головы локоны волос. Теперь же он остался один с этими мгновениями, словно на обрыве между реальностью и воспоминаниями. Тени его боли исказили даже мелодии, которые он раньше так любил; балы и празднества, веселящие молодую душу. Теперь они звучат как гимны утраты, напоминая о том, что навсегда останется лишь эхо того, что было."}),(0,i.jsx)(n.p,{children:'Его глаза, однажды сверкающие от радости, теперь смотрят в никуда, словно он пытается прочитать послание на небесах. Он ищет ответы в бесконечности ночного неба, пытаясь понять, почему именно его жизнь должна быть оплетена такой жестокой участью. Лишь маленькие глаза, напоминающие ему об Эриде — его собственная дочь — не позволила ему попасть под петлю. Такая розочка, вся в Эриду. Сына Август тоже любил, потому что у него был характер Эриды. Да, вот так. "Ты должен потерпеть всего немного, чтобы моя дорогая не злилась, что я оставил детей без присмотра. Я воспитаю их, когда они смогут всё сами, а затем исчезну."'}),(0,i.jsx)(n.p,{children:'Однако пессимистичный и параноидальный Август не верил в смерть Эриды. Она выглядела всегда здоровой. Это стало толчком и целью к тому, чтобы найти, кто убил её. Он готов был душу продать за эту мысль. И он нашёл, спустя время. Это был проклятый Иаго. "Бездушная тварь". Август нашёл его далеко не сразу, однако не было жалко потраченного времени. Пару месяцев расследований, пока свеж след, и немного подкопать. "У тебя же нет денег, куда ты денешься от моей власти." Он подгадывает момент для своей чудотворной охоты, готовясь к ней так, будто пойдёт против стаи медведей, тщательно заготавливая и заряжая огнестрел, держа своих жестоких псов в лёгкой проголоди для того, чтобы они совершили нужное. Август выслеживает дичь. Спустив всех псов, они настегают Иаго в поездке и загрызают, пока Август находит его, полудохлого. Августу приходится постараться, чтобы повторить первое убийство с охотничьим домиком, но всё получается. Там он пытает мальчишку почти неделю, пока не вышибает ему намертво мозги и скармливает собакам, не давая и шанса. Без церемоний. Если девушек он убивал элегантно, то здесь Август позволил себе разъехаться и на теологическом поприще, вспоминая истоки, извращённые и глубокие, отомстить, как он считал нужным. Каждый раз Иаго умирал как в первый — долго, мучительно и безнадежно.'}),(0,i.jsx)(n.p,{children:"Легче Августу, конечно же, не стало. Лишь хуже, ведь это не вернёт Эриду, его душу, на землю. Она унесла её с собой, и хорошо бы, если на небеса, пока тело будет здесь домучивать остальные годы. Вся жизнь обращается точно в комок тумана, налепленный на глаза, порождая в светлом муже забытого деспота. К детям он не был жесток, однако к тем, кто бывал в его доме, он докапывался. То же самое делал во всех сделках. Жизнь не имела смысла, Август терпел дерьмо во рту и едва ли не сплёвывал, вытерпливая до момента, пока он не сможет передать сыну наследство. И хотя к детям он был добродушен и старался скрывать всё, что было на душе, оставшись тем лучшим отцом, внутри повелевало царство Аида. Возможно, это одна из причин, почему это имя всплыло в загробной жизни."}),(0,i.jsx)(n.p,{children:"Август контролирует детей и всё, что вокруг них. Он вспоминает о Рейесе Моргане, герцоге испанском, что пытался с ним сблизиться, вероятно, для правды о смерти Раймона для Эриды. Это был второй раз, когда Август посмел проглотить гордость ради того, чтобы дети были счастливы. Он не передавал опекунства, однако попросил мужчину позаботиться о детях, если его не станет. Спустя еще пару лет девочку он обручит с достойным кандидатом, а сын будет приличным и разумным мальчиком, достойным наследником, если доучится."}),(0,i.jsx)(n.p,{children:"В 50 лет, когда Август осознает, что на этом мессе пора бы и завершиться, он закрывается в комнате Раймона, когда дети уедут в гости к старшей сестре Августа (с ней он из-за детей тоже возобновил общение), долго маркиз будет крутить в голове все события. Здесь, в кабинете, Раймон работал над бумагами и глядел на морские просторы, желая свободы, возвращения. Август же глядел на морские просторы, видя яркий образ улыбчивой любимой, желая свободы и её возвращения. Наконец, он понял Раймона. Вид замер в глазах — он застрелился, осознав, что потерял."})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"...Это был не конец. Как и подобает всем верованиям, кое-что да подтверждается. Август открывает глаза и понимает, что оказывается явно не во сне, ведь здесь нет Эриды. Возможно, она где-то здесь есть, поэтому он без энтузиазма проходит испытания башни и вырывается в наружный мир, для того, чтобы найти её. Вполне вероятно, то отчаяние, что заставляло Августа двигаться, позволило ему найти Эриду. Да, он помнил о ней и грезил даже сквозь потерю воспоминаний; сила его, отозвавшаяся на мучения, ухватила кусочек и не дала украсть в небытие. Так Август не смог забыть её; так он смог найти её. И следовать. Он не помнил всех совершённых зол, а потому смог подружиться с братом вновь, сойтись с сестрой. Едва ли он помнил о том, что находился с ней в браке, однако был рад одному — здорова и перед ним. Он позволил себе наблюдать и набираться сил, тренируясь, пока воспоминания по крупицам будут возвращаться к нему. Однако, справедливости ради, среди них троих Август первым вспомнил свою жизнь, так как Раймон безустанно провоцировал завистливую суть, не забывающую случившегося. Память была лишь затуманена, не более. Когда же воспоминания, спустя годы, возвращаются, они захлёстывают Августа с новой силой. Это заставляет Августа совершенствовать все свои навыки с особым усердием, не готовый к тому, чтобы проиграть любовь Эриды вновь. Однако молчит, с опасением желая узнать, о чём же помнил Раймон и догадывался ли. Особенно его тормозило появление Рейеса Моргана среди мёртвых, но беспокоиться не стоило. Он молчал будто специально, наблюдая и издеваясь над Августом."}),(0,i.jsx)(n.p,{children:"Всю жизнь в Энкраже Август был отречённым от сообщества одиночкой. Единственное, куда он приобщился, это вслед за Эридой, вступив ряды чёрного рынка и выполняя грязную работу, пока не переступит шаг в охотников Забытого Карнавала по сей день. Несколько раз Август пытался намекнуть Эриде и вернуть к ней воспоминания о себе, целых четыре века, только вот она видела в нём лишь кузена. За долгие годы это ранило Августа, настолько, что он поник и более потерял смысл существования, пытаясь найти ту отдушину, что поможет ему хоть как-то забыть об Эриде. Страстью стала лишь охота, что хотя бы ненадолго отвлекает мужчину от бренности. Главное, что он может наблюдать за Эридой и помогать ей, видеть счастливой и игривой. Этого хватит, чтобы существовать, как призрак. Даже если она теперь будет не с ним."})]})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(r,{title:"Факты о персонаже",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Привычки",children:(0,i.jsx)(n.p,{children:"У Августа есть довольно странная привычка: он часто засыпает с книгой в руках. Такое поведение не кажется ему странным, однако почему-то ногицунэ чувствует некоторую связанность чего-то своего внутреннего с миром фантазий и книг. Как он сам отмечает, после такого сна запоминает практически всё содержимое на странице."})}),(0,i.jsx)(h,{title:"Коневодство",children:(0,i.jsx)(n.p,{children:"В далёком прошлом Август крайне интересовался выведением различных мастей на землях Норвегии, однако выведением в Энкраже он не особо занимается, предпочитая оставаться максимально в одиночестве, насколько возможно, дабы не брать ответственность за другую жизнь. К тому же, проблем с Вальгардами ему бы не хотелось иметь. В то ж время, в нём горит любопытство относительно местных потенциальных скакунов и животных, которых можно было бы дрессировать, однако ничего конкретного и цепляющего Август пока не заприметил."})}),(0,i.jsx)(h,{title:"Коллекционер антикварных предметов",children:(0,i.jsx)(n.p,{children:"Август разделяет страсть к искусству и предметам старины, особенно восточным артефактам и античным реликвиям. Он создал в своем небольшом доме огромную коллекцию редких и уникальных предметов из разных эпох. Казалось бы, безделушки, однако так Август удовлетворяет свою завистливость, наблюдая за другими богачами."})}),(0,i.jsx)(h,{title:"Отношение к Морану",children:(0,i.jsx)(n.p,{children:"На самом деле, Август завидует Морану, так как второй смог приблизиться к Эриде и распылить в ней странные чувства. Возможно, это одна из тех причин, почему Август не решается покинуть рынок и работать только на себя, а остаётся рядом и наблюдает. Отношения у него отвратительные ко всем, однако держать маску под рукой не запрещал никто."})}),(0,i.jsx)(h,{title:"Осведомлённость о личности Морана",children:(0,i.jsx)(n.p,{children:"Август знает личность Морана, о его прошлом «Каина», когда искал на германскую ветку информацию."})}),(0,i.jsx)(h,{title:"Любовь к собакам",children:(0,i.jsx)(n.p,{children:"Август обожает собак. Настолько, что в Энкраже его собственная тень непроизвольно обращается в собаку и играет с ним. Она не может атаковать, это лишь этап медитации или раздумий."})}),(0,i.jsx)(h,{title:"Религиозные взгляды",children:(0,i.jsx)(n.p,{children:'У Августа нет определённой религии: несмотря на то, что он был из семьи католиков и получившим образование протестантом, сам же мужчина считает себя атеистом, лишь из "привычки" что-то говоря или следуя традициям. Так он был обучен и выбить из него невозможно, однако тот факт, что бога и чудес нет, Август вбил в голову сразу.'})}),(0,i.jsx)(h,{title:"Отношение к детям",children:(0,i.jsx)(n.p,{children:"В детях Август видел только образ Эриды, а не её саму, поэтому никогда их по-настоящему не любил."})}),(0,i.jsx)(h,{title:"Помешательство на образе Эриды",children:(0,i.jsx)(n.p,{children:"Август помешан на том молодом и чутком образе Эриды, в возрасте 16 лет. Он всегда видел её таковой и не иной. Это стало причиной того, почему он насиловал исключительно молодых девочек. Каждую из них Август впоследствии скармливал собакам, которых разводил и продавал близким друзьям. Они отмечали, что у Августа талант дрессировщика."})})]})}),(0,i.jsx)(r,{title:"Внешность",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Август Линдберг производит впечатление человека, принадлежащего к аристократии позднего шестнадцатого века — не столько по вычурности облика, сколько по манере держаться и тщательно выверенной сдержанности. Его внешность не бросается в глаза сразу – в нём нет помпезности, – но задерживает внимание при более долгом изучении. Лицо Августа бледное, с чётко очерченными чертами. Высокий лоб и глубоко посаженные глаза придают выражению собранность и холодную сосредоточенность, а взгляд светлых, почти бесцветных глаз всегда тяжёлый и прямой; он редко бывает рассеянным и создаёт ощущение пристального наблюдения, даже в моменты покоя. Мимика скупая, контролируемая, из-за чего любые проявления эмоций — особенно улыбка — кажутся не до конца искренними и всегда слегка запоздалыми."}),(0,i.jsx)(n.p,{children:"Тёмно-серые волосы, обычно зачёсанные назад, подчёркивают скурпулёзность в поддержании внешнего вида, даже если он не стремится кричать о нём. С одной стороны, он как бы не придаёт причёске нарочитой аккуратности, предпочитая сдержанную небрежность, допустимую для человека его положения, однако невозможно не заметить в ней стремление обрести задуманную форму. В целом его внешний вид создаёт впечатление ухоженности без излишнего старания — словно порядок вокруг него поддерживается по умолчанию."}),(0,i.jsx)(n.p,{children:"Одежда Августа соответствует его статусу и всегда подобрана со вкусом, ведь ранее мужчина организовывал балы, карнавалы и вёл особо праздную жизнь. Он предпочитает глубокие, насыщенные оттенки — чаще всего синий, чёрный, тёмно-серый. Плащ отдаёт синевой с тёмной атласной подкладкой, под ним — рубашка из тонкой шелковой ткани с серебряным орнаментом, аккуратный воротник жабо и галстук из кружева, лишённый избыточного декора. Кушак из чёрного бархата с золотистой вышивкой выполняет не столько практическую, сколько статусную функцию. Брюки из тонкой шерсти и высокие кожаные сапоги с металлическими пряжками завершают образ."}),(0,i.jsx)(n.p,{children:"Во время особых выходов (на охоту или же в пределах чёрного рынка) Август носит маску Баута, лишённую индивидуальных черт. Её функция прямая и весьма очевидная – полностью сокрыть верхнюю часть лица, дабы его никто не узнавал на миссиях охоты, кокетливо оставляя подбородок открытым. Маска лишена явных признаков пола, возраста или происхождения, что делает фигуру под ней обезличенной. В сочетании с тёмным плащом с капюшоном и треугольной шляпой она превращает его в почти анонимный силуэт, легко растворяющийся в толпе. В этом образе Август как бы отказывается от своего лица, имени и статуса, оставляя лишь шлейф присутствия, сложно связанное с конкретным человеком, но чётко подчеркивая образ – Аид – грозный охотник, готовый покуситься на всё, что было заказано на его имя."})]})}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Стрельба",children:(0,i.jsx)(n.p,{children:"При жизни на охоте, да и в целом культура чёрного рынка, позволяющая напрямую прикоснуться к новшествам наружного мира. Методом проб и ошибок он знакомился с каждым огнестрельным прототипом, начиная от мушкетов, револьверов и заканчивая винтовками, что могли попасть ему в руки, изучал аналоги, заказывал персонально под себя схемы для изучения. Август действительно весьма глубоко проник в оружейную эстетику, понимая, что у него нет иных способов защитить себя без оружия, причем эффективность холодного — это здорового, но на охоте хотелось контактировать с жертвой минимально. А если с огнестрелом правильно поэкспериментировать... В общем, Август сумел добраться до моделей мировых войн, изучив приглядевшиеся и пытаясь воспроизводить их с помощью теней после детальных проб и стрельб. Последние из встретившихся стали СВД и Гаранд времён 1940-х, на которых Август и решил остановиться. Августа нельзя назвать профессиональным стрелком, однако как истинный самоучка и любитель достиг немалого."})}),(0,i.jsx)(h,{title:"Навыки охоты",children:(0,i.jsx)(n.p,{children:"Будучи графом, обладал уникальными навыками охоты, которые были частью его аристократического образа жизни. Он был опытным охотником и знал, как следить за добычей, распознавать следы животных и использовать природные приманки. Охота для Августа была не только развлечением, но и способом проявить своё мастерство, найти меланхолию на задворках жизни и смерти. Более того, Август уже более 300 лет является охотником и работает на чёрный рынок, сделав это своей работой послесмертия. Август, как опытный охотник, обладает умением управлять охотничьими собаками, которые помогали ему в поиске и облаве на дичь во время охоты, чем в Энкраже активно пользуется, преимущественно в теневых прототипах."})}),(0,i.jsx)(h,{title:"Ориентирование на местности",children:(0,i.jsx)(n.p,{children:"Благодаря своему опыту охоты и странствий, Август обладает отличной ориентировкой в природной среде. Он может легко определить стороны света, найти путь в сложных условиях и даже использовать небольшие навигационные приемы, чтобы достичь цели."})}),(0,i.jsx)(h,{title:"Система символов",children:(0,i.jsx)(n.p,{children:"Август разработал свою систему символов и знаков, которые он использует для передачи тайных сообщений или маркировки мест. Это позволяет ему оставаться связанным с другими охотниками и агентами на чёрном рынке, обмениваясь информацией без лишних слов."})}),(0,i.jsx)(h,{title:"Чтение невербальных сигналов",children:(0,i.jsx)(n.p,{children:"Благодаря долгому общению с людьми и тонкой наблюдательности, Август научился читать невербальные сигналы и жесты, распознавать скрытые эмоции и интонации, что делает его мастером в области межличностной коммуникации."})}),(0,i.jsx)(h,{title:"Искусство фехтования",children:(0,i.jsx)(n.p,{children:"Август уделял особое внимание развитию своего фехтовального мастерства и сопутствующих физических характеристик. Он обучался различным стилям фехтования, включая классические европейские стили, однако сконцентрировался на шпаге и рапире. В активном бою не использует, предпочитая отдавать себя магии и полагаясь полностью на неё, однако может взяться за нож или клинок в экстремальных случаях или создать их из плотных теней."})}),(0,i.jsx)(h,{title:"Дрессировка и уход за животными",children:(0,i.jsx)(n.p,{children:"В силу работы на рынок много знает о фауне и флоре, а потому вполне себе мог бы кого-то да разводить."})}),(0,i.jsx)(h,{title:"Феноменальная память",children:(0,i.jsx)(n.p,{children:"У Августа феноменальная память – он может в точности воспроизвести любой текст, прочитанный один раз. Это касается только земной письменности или же тех языков, которые он знает."})}),(0,i.jsx)(h,{title:"Подделка почерка",children:(0,i.jsx)(n.p,{children:"Может подделать даже самый заковыристый почерк."})}),(0,i.jsx)(h,{title:"Маскировка и создание ложных следов",children:(0,i.jsx)(n.p,{children:"Благодаря своему опыту в аристократических кругах и работе на чёрном рынке, Август освоил искусство маскировки своей личности и создания поддельных следов. Он умеет внимательно наблюдать за людьми, анализировать их поведение и манеры, чтобы создать реалистичную маскировку и ввести в заблуждение даже опытных наблюдателей."})}),(0,i.jsx)(h,{title:"Языки",children:(0,i.jsx)(n.p,{children:"Август был многоязычным аристократом и крайне образованным. Он свободно владел норвежским, испанским, датским, немецким. На теологическом факультете обязательными для изучения стали древнееврейский и древнегреческий языки."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Потребность в подпитке негативными эмоциями",children:(0,i.jsx)(n.p,{children:"Ногицунэ нуждаются в постоянной подпитке чужой злостью, ненавистью и прочими негативными эмоциями. Если происходит истощение, то их силы слабеют, а сами они становятся крайне раздражительными и теряют возможность контролировать себя."})}),(0,i.jsx)(h,{title:"Слепота после использования дара",children:(0,i.jsx)(n.p,{children:"Дар ногицунэ может оставить его слепым на продолжительное время. Конечно, несмотря на то, что Август научился более-менее ориентироваться буквально на пустоту и остальные органы чувств, это снижает все добытые характеристики на заметный уровень, делая лиса уязвимым."})}),(0,i.jsx)(h,{title:"Зависимость от теней",children:(0,i.jsx)(n.p,{children:"Август полагается на тени для создания оружия и других предметов. Эта зависимость может быть слабостью в тех случаях, когда он находится в местах с достаточным освещением или лишен доступа к теням, что делает его менее способным в боевых ситуациях."})}),(0,i.jsx)(h,{title:"Уязвимость к серебру",children:(0,i.jsx)(n.p,{children:"Кицунэ особенно боятся серебряного оружия, как и оборотни, из-за чего стараются остерегаться оппонента, у которого есть что-либо из данного материала в любом виде."})}),(0,i.jsx)(h,{title:"Боязнь резких и громких звуков",children:(0,i.jsx)(n.p,{children:"Как и любой зверь, кицунэ боятся резких и громких звуков, которые дезориентируют их, ровно как и высокочастотные звуки."})}),(0,i.jsx)(h,{title:"Консерватизм и страх перед современными технологиями",children:(0,i.jsx)(n.p,{children:"Несмотря на то, что он освоил огнестрельное оружие, Август может испытывать глубокий страх перед современной технологией и её влиянием на мир. Это оставляет его уязвимым в ситуациях, где он сталкивается с высокотехнологичными устройствами. Из-за своего аристократического прошлого и долгой истории, Август слишком консервативен и упорствует в своих взглядах, что иногда мешает ему адаптироваться к изменениям."})}),(0,i.jsx)(h,{title:"Зависимость от охотничьих собак",children:(0,i.jsx)(n.p,{children:"Хотя Август опытен в обучении и управлении охотничьими собаками, его способность охотиться может оказаться ограниченной в случае, если он останется без своих верных спутников."})}),(0,i.jsx)(h,{title:"Чрезмерное честолюбие и недовольство",children:(0,i.jsx)(n.p,{children:"В поиске себя и своего места в новом мире, Август страдает от чрезмерного честолюбия и недовольства своими достижениями, что приводит к постоянному стремлению к большему, беспокойству. Если подойти правильно, его не сложно спровоцировать на опасную и даже рискованную для него авантюру."})}),(0,i.jsx)(h,{title:"Эрида",children:(0,i.jsx)(n.p,{children:"У Августа главной слабостью считается Эрида. Он бросит всё ради того, чтобы помочь ей, а потому она может стать значимым подспорьем, если смочь заточить такую женщину."})}),(0,i.jsx)(h,{title:"Зависть",children:(0,i.jsx)(n.p,{children:"Август не боится быть униженным, не боится втаптывать свою гордость, однако нельзя сказать такого про чувство острой зависти. Как можно понять, жертвы Августа – это чаще всего именно те люди, что смогли получить то, чего у ногицунэ как раз никогда не было, и чем бы он хотел обладать для своего душевного спокойствия. И если вы попытаетесь поддеть его зависть своими успехами, кто знает, может, это заставит действовать решительнее, сломает устоявшийся образ холодного и рассудительного соперника."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsx)(d,{children:(0,i.jsx)(h,{title:"Кристофер Аамодт",children:(0,i.jsx)(n.p,{children:"Близкий друг. Связаны часами на золотой подвеске. Не ходят."})})})})]}),(0,i.jsx)(x,{children:(0,i.jsx)(n.p,{children:"Увы, так, видимо, всегда бывает в нашем мире. Каждый человек обладает тем, что ему совершенно не нужно, а тем, что ему необходимо, владеют другие"})})]})}function s(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:s}={...(0,l.useMDXComponents)(),...e.components};return s?(0,i.jsx)(s,{...e,children:(0,i.jsx)(n,{...e})}):n(e)}])}]);